/**
 * Procédés — the club's tactical exercise library (Pôle technique).
 *
 * Taxonomy is three groupes → phases → principes; every procédé hangs off one
 * principe. Shapes follow the real backend (`/tactical-phases`, `/tactics/search`):
 * `surface` is [largeur, longueur] in metres, `effectif` is [joueurs, gardiens],
 * and `sections` is the free-form ordered rich-text list the backend calls
 * `fields[]` — its titles are normalised here to one consistent set.
 */

export type ProcedeType = "Jeu" | "Situation" | "Exercice"

export type ProcedeGroupe = {
  id: string
  nom: string
  /** Tactical principles vs. the complementary library (échauffements, athlétique…). */
  kind: "principe" | "complementaire"
}

export type ProcedePhase = { id: string; groupeId: string; nom: string }

export type ProcedePrincipe = { id: string; phaseId: string; nom: string }

/** One rich-text block: either a paragraph or a bullet list. */
export type ProcedeSection = {
  titre: string
  texte?: string
  items?: string[]
}

export type ProcedeItem = {
  id: string
  titre: string
  type: ProcedeType
  principeId: string
  /** Minutes, plain string. */
  duree: string
  /** Work structure, e.g. "3*4". */
  sequence: string
  /** Recovery in seconds, plain string. */
  recuperation: string
  /** [largeur, longueur] en mètres. */
  surface: [number, number]
  /** [joueurs, gardiens]. */
  effectif: [number, number]
  materiel: { quantite: number; nom: string }[]
  /** Tactic-board still. */
  image?: string
  /** Has an animated board version. */
  video: boolean
  /** Shared with the other clubs of the network. */
  partage: boolean
  auteur: string
  categories: string[]
  sections: ProcedeSection[]
}

